CREATE TABLE IF NOT EXISTS gis_phase364_integrity_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), certification_version TEXT NOT NULL, features_expected BIGINT NOT NULL DEFAULT 0, features_verified BIGINT NOT NULL DEFAULT 0, certified_count BIGINT NOT NULL DEFAULT 0, revoked_count BIGINT NOT NULL DEFAULT 0, missing_event_count BIGINT NOT NULL DEFAULT 0, broken_chain_count BIGINT NOT NULL DEFAULT 0, hash_mismatch_count BIGINT NOT NULL DEFAULT 0, integrity_status TEXT NOT NULL, report JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());